{"path":"assets/css/styles.css","content":"/* Minimal reset */
:root{
  --bg:#fbfdff;
  --muted:#6b7280;
  --accent1:#7bd389;
  --accent2:#5aa0ff;
  --card:#ffffff;
  --glass:rgba(255,255,255,0.6);
  --radius:14px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial; background:linear-gradient(180deg,var(--bg),#f4fbff);color:#122;line-height:1.45}
.container{max-width:var(--max-width);margin:0 auto;padding:24px}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;z-index:40;background:linear-gradient(180deg,rgba(255,255,255,0.7),rgba(255,255,255,0.55));border-bottom:1px solid rgba(10,10,10,0.04)}
.header-inner{display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;align-items:center;text-decoration:none;color:inherit}
.logo{width:160px;height:42px}
.nav ul{display:flex;gap:12px;list-style:none;margin:0;padding:0}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#fff}
.nav-toggle{display:none;background:none;border:0;font-size:20px}

.hero{padding:48px 0;background-image:url('../assets/img/pattern.svg');background-size:cover;background-repeat:no-repeat}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
.hero-copy h1{font-size:28px;margin:0 0 12px}
.hero-copy .lead{color:var(--muted);margin-bottom:16px}
.hero-cta .btn{margin-right:10px}
.meta-list{display:flex;gap:16px;font-size:14px;color:var(--muted);list-style:none;padding:0;margin-top:12px}

.card.mosaic{height:220px;border-radius:18px;overflow:hidden;box-shadow:0 10px 30px rgba(20,30,50,0.08);display:flex;align-items:flex-end}
.card .pattern{position:absolute;opacity:0.9}
.stats{padding:20px;background:linear-gradient(180deg,transparent,rgba(255,255,255,0.95));width:100%}

section{padding:40px 0}
h2{margin:0 0 12px;font-size:22px}
.intro{color:var(--muted);margin-bottom:16px}
.ritual-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.ritual-card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(15,20,30,0.04)}

.expect-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.step{background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff);padding:14px;border-radius:12px}

.schedule-list{list-style:none;padding:0;color:var(--muted)}

.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:12px}
.price-card{background:var(--card);padding:20px;border-radius:14px;box-shadow:0 8px 28px rgba(10,20,40,0.04);text-align:center}
.price-card.featured{transform:translateY(-8px);border:1px solid rgba(90,160,255,0.12)}
.rate{font-size:20px;margin:8px 0}
.disclaimer{font-size:13px;color:var(--muted);margin-top:12px}

.faq-list details{background:var(--card);border-radius:10px;padding:12px;margin-bottom:10px}
.faq-list summary{cursor:pointer;font-weight:600}
.answer{color:var(--muted);margin-top:8px}

.cta{background:linear-gradient(90deg,rgba(123,211,137,0.08),rgba(90,160,255,0.06));padding:26px;border-radius:16px;display:flex;align-items:center;justify-content:space-between}
.cta .big{padding:14px 22px}

.btn{display:inline-block;padding:10px 14px;border-radius:10px;background:#fff;border:1px solid rgba(10,10,10,0.06);text-decoration:none;color:#122}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#fff;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(18,34,44,0.06)}

.site-footer{border-top:1px solid rgba(10,10,10,0.04);padding:24px 0;background:transparent}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.legal{padding-top:12px;color:var(--muted);font-size:13px}

/* Responsive */
@media (max-width:980px){
  .hero-grid{grid-template-columns:1fr}
  .ritual-grid{grid-template-columns:1fr}
  .expect-grid{grid-template-columns:1fr 1fr}
  .pricing-grid{grid-template-columns:1fr}
  .nav ul{display:none}
  .nav-toggle{display:block}
}
@media (max-width:520px){
  .expect-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // set current year
  var y = new Date().getFullYear();
  var el = document.getElementById('year'); if(el) el.textContent = y;

  // mobile nav toggle
  var toggle = document.getElementById('nav-toggle');
  var nav = document.getElementById('main-nav');
  toggle && toggle.addEventListener('click',function(){
    if(nav.classList.contains('open')){nav.classList.remove('open');toggle.textContent='☰'}
    else{nav.classList.add('open');toggle.textContent='✕'}
  });

  // smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id = this.getAttribute('href').slice(1);
      var target = document.getElementById(id);
      if(target){ target.scrollIntoView({behavior:'smooth',block:'start'}); }
    });
  });

  // FAQ details polyfill-ish: close siblings when opening
  document.querySelectorAll('.faq-list details').forEach(function(d){
    d.addEventListener('toggle',function(){
      if(d.open){
        document.querySelectorAll('.faq-list details').forEach(function(other){ if(other!==d) other.open=false; });
      }
    });
  });

  // simple CTA analytics (no external network)
  document.querySelectorAll('a[href]').forEach(function(a){
    a.addEventListener('click',function(){
      try{console.log('link-click',this.getAttribute('href'))}catch(e){}
    });
  });
});
"} 
{"path":"assets/img/pattern.svg","content":"<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600" viewBox="0 0 800 600">
